  else if (v.c === C.smoke) smokeVoxels.push(v);
  else opaqueVoxels.push(v);
});

function buildMesh(list, materialOptions, castsShadow) {
  var m = new THREE.InstancedMesh(
    geom, new THREE.MeshLambertMaterial(Object.assign({ color: 0xffffff }, materialOptions)), list.length
  );
  list.forEach(function (v, i) {
    dummy.position.set(v.x, v.y + 0.5, v.z);
    dummy.updateMatrix();
    m.setMatrixAt(i, dummy.matrix);
    m.setColorAt(i, color.setHex(v.c));
  });
  if (m.instanceColor) m.instanceColor.needsUpdate = true;
  m.castShadow = !!castsShadow;
  m.receiveShadow = !!castsShadow;
  scene.add(m);
