#!/usr/bin/env node
/**
 * Deterministic headless-Chrome screenshot via the DevTools Protocol.
 *
 * Why not `--screenshot` + `--virtual-time-budget`:
 *   - this machine's Chrome lingers on GoogleUpdater/crashpad helpers, so the
 *     process never exits and the caller hangs;
 *   - the page runs a perpetual requestAnimationFrame loop, so virtual time may
 *     never be exhausted and the screenshot never fires.
 * Here we drive a real browser over CDP: navigate, wait wall-clock time,
 * capture, then kill the browser. It also reports JS exceptions and lets us
 * evaluate expressions, which is what turns a screenshot into evidence.
 *
 * Usage: node shot.mjs <url> <out.png> [waitMs] [width] [height] [evalExpr]
 */
import { spawn } from 'node:child_process';
import fs from 'node:fs';

const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const [url, out, waitMsArg, widthArg, heightArg, evalExpr] = process.argv.slice(2);
if (!url || !out) {
  console.error('usage: node shot.mjs <url> <out.png> [waitMs] [width] [height] [evalExpr]');
  process.exit(2);
}
const waitMs = Number(waitMsArg || 4000);
const width = Number(widthArg || 1400);
const height = Number(heightArg || 880);
const port = 9222 + Math.floor(Math.random() * 300);
const profile = fs.mkdtempSync('/tmp/cdp-profile-');

const chrome = spawn(CHROME, [
  '--headless=new',
  '--remote-debugging-port=' + port,
  '--user-data-dir=' + profile,
  '--no-first-run', '--no-default-browser-check',
  '--disable-component-update', '--disable-background-networking',
  '--disable-crash-reporter', '--disable-breakpad', '--disable-sync',
  '--disable-gpu', '--enable-unsafe-swiftshader',
  '--use-gl=angle', '--use-angle=swiftshader',
  '--hide-scrollbars', '--mute-audio',
  '--window-size=' + width + ',' + height,
  'about:blank',
], { stdio: ['ignore', 'ignore', 'pipe'] });

function cleanup(code) {
  try { chrome.kill('SIGKILL'); } catch {}
  try { fs.rmSync(profile, { recursive: true, force: true }); } catch {}
  process.exit(code);
}

async function waitForDevtools(timeoutMs = 20000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const r = await fetch(`http://127.0.0.1:${port}/json/version`);
      if (r.ok) return await r.json();
    } catch {}
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error('devtools endpoint did not come up');
}

const version = await waitForDevtools();
const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = targets.find((t) => t.type === 'page');
if (!page) throw new Error('no page target');

const ws = new WebSocket(page.webSocketDebuggerUrl);
